func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
    if len(in.Clusters) == 0 {
        return ReleasePlan{}, fmt.Errorf("没有可发布的集群：未提供候选集群")
    }
    // sort copies by ID
    selected := []string{}
    excluded := []ExcludedCluster{}
    for _, c := range in.Clusters {
        switch {
        case c.Disabled:
            excluded = append(excluded, ExcludedCluster{c.ID, ReasonDisabled})
        case matchesAny(c.Tags, in.Exclude):
            excluded = append(excluded, ExcludedCluster{c.ID, ReasonExcludeMatched})
        case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
            excluded = append(excluded, ExcludedCluster{c.ID, ReasonIncludeNotMatched})
        default:
            selected = append(selected, c.ID)
        }
    }
    sort.Strings(selected)
    sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
    if len(selected) == 0 {
        var b strings.Builder
        b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
        for _, e := range excluded {
            b.WriteString(fmt.Sprintf("\n  %s：%s", e.ID, e.Reason))
        }
        return ReleasePlan{}, errors.New(b.String())
    }
    batches := []Batch{}
    for i := 0; i < len(selected); i += in.BatchSize {
        end := i + in.BatchSize
        if end > len(selected) { end = len(selected) }
        batches = append(batches, Batch{Index: len(batches)+1, Clusters: selected[i:end]})
    }
    return ReleasePlan{App: AppInfo{...}, Batches: batches, Excluded: excluded}, nil
}
```

